operation.add:
{% if 'ultimatemenu/menu.js' not in script and ((class|slice(0, 16) != 'product-category' and class|slice(0, 15) != 'product-product' and class|slice(0, 11) != 'common-home') or 'ocdevwizard/form_builder/global.js' not in script) %}
{% if class|slice(0, 15) == 'product-product' and (script == 'catalog/view/javascript/jquery/magnific/jquery.magnific-popup.min.js' or script == 'catalog/view/javascript/jquery/swiper/js/swiper.jquery.js' or script == 'catalog/view/javascript/plaza/swatches/swatches.js' or script == 'catalog/view/javascript/plaza/cloudzoom/cloud-zoom.1.0.2.min.js' or script == 'catalog/view/javascript/plaza/cloudzoom/zoom.js') %}
<script src="{{ script }}" defer></script>
{% else %}
<script src="{{ script }}" ></script>
{% endif %}
{% endif %}

{% if class|slice(0, 16) == 'product-category' or class|slice(0, 15) == 'product-product' %}
<script src="catalog/view/javascript/common.js" defer></script>
{% else %}
<script src="catalog/view/javascript/common.js" ></script>
{% endif %}

{% if class|slice(0, 16) == 'product-category' or class|slice(0, 15) == 'product-product' %}
<script src="catalog/view/javascript/bootstrap/js/bootstrap.min.js" defer></script>
{% else %}
<script src="catalog/view/javascript/bootstrap/js/bootstrap.min.js" ></script>
{% endif %}
